/* Feature: 00-workspace.js */
(() => {
 const e=escapeHtml;
 let data=null;
 const listeners=new Set();
 async function load(){data=await AppAuth.api('/api/workspace');document.getElementById('personaBadge').textContent=data.persona.name;for(const f of listeners)f(data);return data}
 async function mutate(path,method='POST',body={}){const result=await AppAuth.api('/api/workspace'+path,{method,...(method==='DELETE'?{}:{body:JSON.stringify(body)})});await load();return result}
 const panel=(title,content)=>`<section class="panel"><h2 class="panel-title">${e(title)}</h2>${content}</section>`;
 const btn=(label,attrs='',secondary=false)=>`<button class="detail-button ${secondary?'secondary':''}" ${attrs}>${label}</button>`;
 const input=(id,label,attrs='')=>`<label for="${id}">${label}</label><input id="${id}" class="detail-input" ${attrs}>`;
 const json=v=>`<pre class="detail-code">${e(JSON.stringify(v,null,2))}</pre>`;
 function form(title,content,handler){detail(title,`<form id="workspaceForm">${content}<p id="workspaceError" class="error-message" role="alert"></p>${btn('Save','type="submit"')}</form>`);document.getElementById('workspaceForm').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('[type=submit]');b.disabled=true;try{await handler();closeDetail()}catch(err){document.getElementById('workspaceError').textContent=err.message;b.disabled=false}}}
 const value=id=>document.getElementById(id).value.trim();
 const badge=status=>`<span class="badge ${status==='succeeded'?'success':['failed','expired'].includes(status)?'danger':''}">${e(status)}</span>`;
 const error=(root,err)=>{root.innerHTML=panel('Unable to load workspace',`<p role="alert" class="error-message">${e(err.message)}</p>${btn('Retry','data-retry')}`);root.querySelector('[data-retry]').onclick=()=>load().catch(x=>error(root,x))};
 async function mount(root,render){listeners.add(d=>render(d));if(data)render(data);else{root.innerHTML='<p class="muted">Loading workspace…</p>';try{await load()}catch(err){error(root,err)}}}
 function inspectRun(run){detail('Execution · '+run.status,`<p class="muted">${e(run.id)} · ${e(run.started_at)} · ${run.duration_ms??'—'} ms</p>${run.error?`<p class="error-message">${e(run.error)}</p>`:''}<h3>Input</h3>${json(run.input)}<h3>Tool execution steps</h3>${run.steps.map(s=>`<div class="record-row"><b>${e(s.toolName||s.agentName)}</b> ${badge(s.status)}<p class="muted">${e(s.method||'')} ${e(s.endpoint||'')} · ${s.durationMs} ms${s.approved?' · Change approved':''}</p>${s.steps?.length?`<p class="muted">${s.steps.map(x=>e(x.toolName)+' · '+e(x.status)).join(' → ')}</p>`:''}${json(s.output??s.error)}</div>`).join('')||'<p class="muted">No steps completed.</p>'}<h3>Output</h3>${json(run.output)}`)}
 function agentTools(agent){return agent.mode==='reasoning'?agent.toolIds:agent.steps.map(s=>s.toolId)}
 window.Workspace=Object.freeze({get:()=>data,load,mutate,mount,panel,btn,input,json,form,value,badge,inspectRun,runForm,agentTools,e});
 Aether.registerFeature({id:'dashboard',label:'Overview',icon:'layout-dashboard',description:'Your connected tools, configured agents and recorded execution activity.',mount({root}){
  mount(root,d=>{root.innerHTML=`<p class="workspace-note">${e(d.persona.name)} · ${e(d.persona.description)}</p><div class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6">${[['Registered tools',d.tools.length,'tools'],['Configured agents',d.agents.length,'agents'],['Knowledge sources',d.documents.length,'knowledge-fabric'],['Recorded executions',d.runs.length,'executions']].map(([title,n,route])=>panel(title,`<p class="metric-value">${n}</p><button data-route="${route}" class="text-sm text-blue-700">Open ${e(title.toLowerCase())} →</button>`)).join('')}</div>${!d.tools.length&&!d.agents.length?`<div class="mb-6">${panel('Set up your workspace',`<p class="muted mb-4">Register a REST tool, bind it to an agent, and execute it to record your first result. Connect an existing Python agent through Infrastructure Integrations if it runs inside your network.</p><div class="page-actions">${btn('Register a tool','data-route="tools"')}${btn('Add knowledge','data-route="knowledge-fabric"',true)}${btn('Connect a gateway','data-route="infrastructure"',true)}</div>`)}</div>`:''}${panel('Recent executions',d.runs.length?d.runs.slice(0,8).map(r=>`<div class="record-row flex flex-wrap justify-between items-center gap-3"><div><b>${e(d.agents.find(a=>a.id===r.agent_id)?.name||d.tools.find(t=>t.id===r.tool_id)?.name||d.orchestrations.find(f=>f.id===r.agent_id)?.name||'Execution')}</b><p class="muted">${e(new Date(r.started_at).toLocaleString())} · ${r.duration_ms??'—'} ms</p></div><div>${badge(r.status)} ${btn('Inspect',`data-run="${r.id}"`,true)}</div></div>`).join(''):'<p class="empty-state">No executions yet. This view fills with actual tool and agent results.</p>')}`;root.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>Aether.navigate(b.dataset.route));root.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>inspectRun(d.runs.find(r=>r.id===b.dataset.run)))})
 }});
 Aether.registerFeature({id:'tools',label:'Tool Integrations',icon:'plug',description:'Register REST capabilities and expose them to agents through validated inputs.',mount({root,notify}){
  function edit(tool){form(tool?'Edit tool':'Register tool',`${input('toolName','Tool name','required maxlength="100" value="'+e(tool?.name||'')+'"')}${input('toolDescription','Description','maxlength="1000" value="'+e(tool?.description||'')+'"')}${input('toolEndpoint','HTTPS endpoint','type="url" required value="'+e(tool?.endpoint||'')+'" placeholder="https://your-service.com/api/resource"')}<p class="form-help">Use a fixed public endpoint. GET input becomes query parameters; other methods receive a JSON body. Private services use infrastructure gateways.</p><div class="form-row"><div><label for="toolMethod">HTTP method</label><select id="toolMethod" class="detail-input">${['GET','POST','PUT','PATCH','DELETE'].map(m=>`<option ${m===tool?.method?'selected':''}>${m}</option>`).join('')}</select></div><div>${input('toolSecret','Credential reference','pattern="TOOL_[A-Z0-9_]+" value="'+e(tool?.secretRef||'')+'" placeholder="TOOL_SERVICE_TOKEN"')}</div></div><p class="form-help">Optional credential. Save a token in Credentials, then use its reference here. Hosting environment references are also supported.</p><div class="form-row"><div><label for="toolAuth">Authentication</label><select id="toolAuth" class="detail-input">${[['bearer','Bearer token'],['api-token','Api-Token'],['api-key','API key header'],['basic','Basic (base64 username:password)']].map(([id,label])=>`<option value="${id}" ${id===(tool?.authType||'bearer')?'selected':''}>${label}</option>`).join('')}</select></div><div><label for="toolHeader">API key header</label><select id="toolHeader" class="detail-input">${['X-API-Key','api-key','X-Auth-Token'].map(h=>`<option ${h===tool?.headerName?'selected':''}>${h}</option>`).join('')}</select></div></div><label for="toolSchema">Input schema (JSON)</label><textarea id="toolSchema" class="detail-input font-mono" rows="7" required>${e(JSON.stringify(tool?.inputSchema||{type:'object',properties:{},additionalProperties:false},null,2))}</textarea><p class="form-help">Supported: type, properties, required, items, enum, additionalProperties, title and description.</p><label class="block mb-3"><input id="toolApproval" type="checkbox" ${tool?.requiresApproval?'checked':''}> Require administrator approval (always required for write methods)</label><label class="block mb-3"><input id="toolEnabled" type="checkbox" ${tool?.enabled===false?'':'checked'}> Enabled</label>`,()=>mutate('/tools'+(tool?'/'+tool.id:''),tool?'PUT':'POST',{name:value('toolName'),description:value('toolDescription'),endpoint:value('toolEndpoint'),method:value('toolMethod'),authType:value('toolAuth'),headerName:value('toolHeader'),secretRef:value('toolSecret'),inputSchema:JSON.parse(value('toolSchema')),requiresApproval:document.getElementById('toolApproval').checked,enabled:document.getElementById('toolEnabled').checked,...(tool?{revision:tool.revision}:{})}))}
  mount(root,d=>{const admin=d.persona.id==='administrator';root.innerHTML=`<div class="page-actions">${admin?btn('Register tool','id="addTool"'):''}${btn('Refresh','id="refreshTools"',true)}<span class="muted">${d.tools.length} integrations</span></div>${panel('Registered tools',d.tools.length?d.tools.map(t=>`<article class="record-row"><div class="flex flex-wrap justify-between gap-3"><div><h3 class="font-semibold">${e(t.name)}</h3><p class="muted">${e(t.description)}</p><p class="muted font-mono mt-2">${e(t.method)} ${e(t.endpoint)}</p><div class="mt-2">${badge(t.enabled?'Enabled':'Disabled')} ${badge(t.requiresApproval?'Approval required':'Read-only')} ${badge(t.credentialConfigured?'Credential ready':'Credential missing')}</div></div><div>${btn('Schema',`data-tool-schema="${t.id}"`,true)}${d.persona.execute?btn('Test / invoke',`data-invoke="${t.id}" ${!t.enabled?'disabled':''}`):''}${admin?btn('Edit',`data-edit-tool="${t.id}"`,true)+btn('Remove',`data-remove-tool="${t.id}"`,true):''}</div></div></article>`).join(''):'<p class="empty-state">No tools registered. Add an endpoint and input schema to expose a real capability to your agents.</p>')}`;
   root.querySelector('#addTool')?.addEventListener('click',()=>edit());root.querySelector('#refreshTools').onclick=()=>load().catch(err=>notify(err.message,'danger'));root.querySelectorAll('[data-edit-tool]').forEach(b=>b.onclick=()=>edit(d.tools.find(t=>t.id===b.dataset.editTool)));root.querySelectorAll('[data-remove-tool]').forEach(b=>b.onclick=async()=>{try{await mutate('/tools/'+b.dataset.removeTool,'DELETE')}catch(err){notify(err.message,'danger')}});root.querySelectorAll('[data-tool-schema]').forEach(b=>b.onclick=()=>{const t=d.tools.find(t=>t.id===b.dataset.toolSchema);detail(t.name+' · Input schema',json(t.inputSchema))});root.querySelectorAll('[data-invoke]').forEach(b=>b.onclick=()=>runForm(d.tools.find(t=>t.id===b.dataset.invoke),'tools',d.persona))
  })
 }});
 function runForm(target,kind,p){const d=data,toolIds=kind==='orchestrations'?target.stages.flatMap(s=>agentTools(d.agents.find(a=>a.id===s.agentId)||{steps:[]})):kind==='agents'?agentTools(target):[target.id],approval=toolIds.some(id=>d.tools.find(t=>t.id===id)?.requiresApproval);if(approval&&!p.approve){Aether.notify('An administrator must approve and execute this workflow.','warn');return}detail('Run '+target.name,`<form id="runWorkspaceForm"><label for="executionInput">Input (JSON object)</label><textarea id="executionInput" class="detail-input font-mono" rows="7" required>{}</textarea>${kind==='agents'&&target.mode==='reasoning'?`<details class="mb-4"><summary class="text-sm text-blue-700 cursor-pointer">Required input schema</summary>${json(target.inputSchema)}</details>`:''}<p class="muted mb-4">This invokes the registered endpoint${kind==='agents'?'s in sequence':''}. Inputs and results are recorded in the workspace.</p>${approval?'<label class="block mb-4"><input id="executionApproval" type="checkbox" required> I approve these tool calls and their potential changes.</label>':''}<p id="executionError" role="alert" class="error-message"></p>${btn('Execute','type="submit"')}</form>`);document.getElementById('runWorkspaceForm').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;b.textContent='Executing…';try{const result=await AppAuth.api('/api/workspace/'+kind+'/'+target.id+'/run',{method:'POST',body:JSON.stringify({input:JSON.parse(value('executionInput')),approved:document.getElementById('executionApproval')?.checked||false})});await load();const run=data.runs.find(r=>r.id===result.id);inspectRun(run)}catch(err){document.getElementById('executionError').textContent=err.message;await load();b.disabled=false;b.textContent='Execute'}}}
 if(window.AETHER_USER?.role==='admin')Aether.registerFeature({id:'credentials',label:'Credentials',icon:'key-round',description:'Encrypted server-side credentials for your tools and model connections.',mount({root,notify}){mount(root,d=>{root.innerHTML=`<div class="page-actions">${btn('Add / rotate credential','id="addCredential"')}</div>${panel('Credential references',`<p class="muted mb-4">Tokens are encrypted on the server. Saved values are never returned to the browser. Use a reference below when configuring a tool or model.</p>${d.credentials.length?d.credentials.map(c=>`<div class="record-row flex flex-wrap items-center justify-between gap-3"><div><b>${e(c.name)}</b><p class="muted">Updated ${e(new Date(c.updated_at).toLocaleString())}</p></div>${btn('Remove',`data-remove-credential="${e(c.name)}"`,true)}</div>`).join(''):'<p class="empty-state">No credentials saved. Public tools can run without a token.</p>'}`)}`;root.querySelector('#addCredential').onclick=()=>form('Save credential',`${input('credentialName','Reference name','required pattern="(TOOL|MODEL)_[A-Z0-9_]+" maxlength="100" placeholder="TOOL_SERVICE_TOKEN"')}${input('credentialSecret','API token or encoded Basic credential','required type="password" autocomplete="new-password" maxlength="8000"')}<p class="muted">Use TOOL_ for a tool or MODEL_ for a model. Saving an existing name rotates the credential for every connection using it.</p>`,()=>mutate('/credentials','POST',{name:value('credentialName'),secret:value('credentialSecret')}));root.querySelectorAll('[data-remove-credential]').forEach(b=>b.onclick=()=>mutate('/credentials/'+b.dataset.removeCredential,'DELETE').catch(err=>notify(err.message,'danger')))})}});
 Aether.registerFeature({id:'agents',label:'Agent Garden',icon:'workflow',description:'Manage reasoning agents and executable tool workflows built from your integrations.',mount({root,notify}){
  function edit(agent){const d=data;if(agent?.mode==='reasoning'){form('Edit reasoning agent',`${input('reasoningName','Agent name','required maxlength="100" value="'+e(agent.name)+'"')}${input('reasoningDescription','Purpose','maxlength="1000" value="'+e(agent.description)+'"')}<label for="reasoningInstruction">Instructions</label><textarea id="reasoningInstruction" class="detail-input" rows="7" required maxlength="6000">${e(agent.instruction)}</textarea><label for="reasoningModel">Model connection</label><select id="reasoningModel" class="detail-input">${d.models.map(m=>`<option value="${m.id}" ${m.id===agent.modelId?'selected':''}>${e(m.name)}</option>`).join('')}</select><label for="reasoningInputSchema">Run input schema</label><textarea id="reasoningInputSchema" class="detail-input font-mono" rows="5">${e(JSON.stringify(agent.inputSchema,null,2))}</textarea><h3>Bound tools</h3>${d.tools.map(t=>`<label class="block mb-3"><input type="checkbox" data-reasoning-tool="${t.id}" ${agent.toolIds.includes(t.id)?'checked':''}> ${e(t.name)} · ${e(t.method)}</label>`).join('')}<label class="block mt-4"><input id="reasoningEnabled" type="checkbox" ${agent.enabled?'checked':''}> Enabled</label>`,()=>mutate('/agents/'+agent.id,'PUT',{mode:'reasoning',name:value('reasoningName'),description:value('reasoningDescription'),instruction:value('reasoningInstruction'),modelId:value('reasoningModel'),inputSchema:JSON.parse(value('reasoningInputSchema')),toolIds:Array.from(document.querySelectorAll('[data-reasoning-tool]:checked'),x=>x.dataset.reasoningTool),enabled:document.getElementById('reasoningEnabled').checked,revision:agent.revision}));return}if(!d.tools.length){notify('Register a tool before creating an agent.');Aether.navigate('tools');return}let steps=structuredClone(agent?.steps||[{toolId:d.tools[0].id,inputFrom:'input',input:{}}]);
   form(agent?'Edit agent':'Create agent',`${input('agentName','Agent name','required maxlength="100" value="'+e(agent?.name||'')+'"')}${input('agentDescription','Purpose','maxlength="1000" value="'+e(agent?.description||'')+'"')}<h3>Tool workflow</h3><p class="muted">Steps run in order and stop on failure. Choose the input source for each tool.</p><div id="agentStepEditor"></div>${btn('Add tool step','id="addAgentStep" type="button"',true)}<label class="block my-4"><input id="agentEnabled" type="checkbox" ${agent?.enabled===false?'':'checked'}> Enabled</label>`,()=>{capture();return mutate('/agents'+(agent?'/'+agent.id:''),agent?'PUT':'POST',{name:value('agentName'),description:value('agentDescription'),steps,enabled:document.getElementById('agentEnabled').checked,...(agent?{revision:agent.revision}:{})})});
   function capture(){steps=steps.map((step,i)=>({toolId:document.getElementById('agentStepTool'+i).value,inputFrom:document.getElementById('agentStepSource'+i).value,input:document.getElementById('agentStepSource'+i).value==='fixed'?JSON.parse(document.getElementById('agentStepFixed'+i).value):{}}))}
   function renderSteps(){document.getElementById('agentStepEditor').innerHTML=steps.map((step,i)=>`<div class="record-row"><div class="flex justify-between items-center"><b class="text-sm">Step ${i+1}</b>${btn('Remove',`type="button" data-remove-step="${i}" ${steps.length===1?'disabled':''}`,true)}</div><div class="form-row"><div><label for="agentStepTool${i}">Tool</label><select id="agentStepTool${i}" class="detail-input">${d.tools.map(t=>`<option value="${t.id}" ${t.id===step.toolId?'selected':''}>${e(t.name)} · ${e(t.method)}</option>`).join('')}</select></div><div><label for="agentStepSource${i}">Input source</label><select id="agentStepSource${i}" class="detail-input">${[['input','Run input'],['previous','Previous tool output'],['fixed','Fixed JSON input']].map(([id,label])=>`<option value="${id}" ${id===step.inputFrom?'selected':''}>${label}</option>`).join('')}</select></div></div><div id="agentStepFixedWrap${i}" ${step.inputFrom==='fixed'?'':'hidden'}><label for="agentStepFixed${i}">Fixed input</label><textarea id="agentStepFixed${i}" class="detail-input font-mono" rows="3">${e(JSON.stringify(step.input||{},null,2))}</textarea></div></div>`).join('');steps.forEach((step,i)=>{document.getElementById('agentStepSource'+i).onchange=ev=>{document.getElementById('agentStepFixedWrap'+i).hidden=ev.target.value!=='fixed'}});document.querySelectorAll('[data-remove-step]').forEach(b=>b.onclick=()=>{try{capture();steps.splice(Number(b.dataset.removeStep),1);renderSteps()}catch(err){notify('Enter valid fixed JSON before changing steps.','warn')}})}
   document.getElementById('addAgentStep').onclick=()=>{if(steps.length>=12){notify('An agent supports up to 12 steps.','warn');return}try{capture();steps.push({toolId:d.tools[0].id,inputFrom:'input',input:{}});renderSteps()}catch{notify('Enter valid fixed JSON before adding a step.','warn')}};renderSteps()
  }
  mount(root,d=>{root.innerHTML=`<div class="page-actions">${d.persona.configure?btn('Build with natural language','id="buildNaturalAgent"')+btn('Create tool workflow','id="addAgent"',true):''}${btn('Refresh','id="refreshAgents"',true)}<span class="muted">Reasoning agents choose bound tools · workflows run configured steps</span></div>${panel('Agent Garden',d.agents.length?d.agents.map(a=>`<article class="record-row"><div class="flex flex-wrap justify-between gap-3"><div><h3 class="font-semibold">${e(a.name)}</h3><p class="muted">${e(a.description)}</p><p class="muted mt-2">${agentTools(a).map(id=>e(d.tools.find(t=>t.id===id)?.name||'Missing tool')).join(a.mode==='reasoning'?' · ':' → ')}</p>${badge(a.enabled?'Enabled':'Disabled')} ${badge(a.mode==='reasoning'?'Reasoning agent':'Tool workflow')}${a.mode==='reasoning'?`<p class="muted mt-2">${e(a.instruction.slice(0,180))}</p>`:''}</div><div>${btn('Details',`data-agent-details="${a.id}"`,true)}${d.persona.execute?btn('Run agent',`data-run-agent="${a.id}" ${!a.enabled?'disabled':''}`):''}${d.persona.configure?btn('Edit',`data-edit-agent="${a.id}"`,true)+btn('Remove',`data-remove-agent="${a.id}"`,true):''}</div></div></article>`).join(''):'<p class="empty-state">No agents configured. Bind your tools into a workflow to run them together.</p>')}`;root.querySelector('#buildNaturalAgent')?.addEventListener('click',()=>Aether.navigate('agent-builder'));root.querySelector('#addAgent')?.addEventListener('click',()=>edit());root.querySelector('#refreshAgents').onclick=()=>load().catch(err=>notify(err.message,'danger'));root.querySelectorAll('[data-edit-agent]').forEach(b=>b.onclick=()=>edit(d.agents.find(a=>a.id===b.dataset.editAgent)));root.querySelectorAll('[data-agent-details]').forEach(b=>b.onclick=()=>{const a=d.agents.find(a=>a.id===b.dataset.agentDetails);detail(a.name,`<p class="muted">${e(a.description)}</p><h3>${a.mode==='reasoning'?'Execution instructions':'Tool workflow'}</h3>${a.mode==='reasoning'?`<p class="chat-content">${e(a.instruction)}</p><h3>Input schema</h3>${json(a.inputSchema)}`:json(a.steps)}<h3>Bound tools</h3>${agentTools(a).map(id=>{const t=d.tools.find(t=>t.id===id);return `<div class="record-row"><b>${e(t?.name||'Missing tool')}</b>${json(t?.inputSchema)}</div>`}).join('')}`)});root.querySelectorAll('[data-run-agent]').forEach(b=>b.onclick=()=>runForm(d.agents.find(a=>a.id===b.dataset.runAgent),'agents',d.persona));root.querySelectorAll('[data-remove-agent]').forEach(b=>b.onclick=()=>mutate('/agents/'+b.dataset.removeAgent,'DELETE').catch(err=>notify(err.message,'danger')))
  })
 }});
 Aether.registerFeature({id:'executions',label:'Execution History',icon:'list-checks',description:'Recorded inputs, outputs, failures and timing for tool and agent calls.',mount({root,notify}){mount(root,d=>{root.innerHTML=`<div class="page-actions">${btn('Refresh','id="refreshExecutions"',true)}</div>${panel('Tool and agent executions',d.runs.length?`<div class="overflow-auto"><table class="w-full text-sm text-left"><thead><tr><th>Agent / tool</th><th>Status</th><th>Started</th><th>Duration</th><th>Evidence</th></tr></thead><tbody>${d.runs.map(r=>`<tr class="border-t"><td>${e(d.agents.find(a=>a.id===r.agent_id)?.name||d.tools.find(t=>t.id===r.tool_id)?.name||d.orchestrations.find(f=>f.id===r.agent_id)?.name||r.id)}</td><td>${badge(r.status)}</td><td>${e(new Date(r.started_at).toLocaleString())}</td><td>${r.duration_ms??'—'} ms</td><td>${btn('Inspect',`data-inspect-run="${r.id}"`,true)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-state">No execution records. Run a tool or an agent to collect evidence here.</p>')}`;root.querySelector('#refreshExecutions').onclick=()=>load().catch(err=>notify(err.message,'danger'));root.querySelectorAll('[data-inspect-run]').forEach(b=>b.onclick=()=>inspectRun(d.runs.find(r=>r.id===b.dataset.inspectRun)))})}});
 Aether.registerFeature({id:'personas',label:'Personas & Access',icon:'contact-round',description:'Different working roles with backend-enforced permissions.',mount({root,notify}){mount(root,d=>{root.innerHTML=`<div class="grid grid-cols-1 md:grid-cols-2 gap-5 mb-6">${d.personas.map(p=>panel(p.name,`<p class="muted">${e(p.description)}</p><div class="mt-4">${badge(p.id===d.persona.id?'Your persona':p.id)} ${badge(p.configure?'Configure':'View')} ${badge(p.execute?'Execute':'Read only')} ${p.approve?badge('Approve changes'):''}</div><p class="muted mt-3">${p.id==='builder'?'Tool credentials and model connections remain administrator-managed.':''}</p>`)).join('')}</div><div class="page-actions">${btn('Refresh access','id="refreshPersonas"',true)}</div>${d.persona.id==='administrator'?panel('Assign user personas',d.users.map(u=>`<div class="record-row flex flex-wrap justify-between gap-3 items-center"><b>${e(u.username)}</b>${u.role==='admin'?badge('Platform administrator'):`<label class="flex items-center gap-3">Persona<select class="detail-input" style="width:auto;margin:0" data-persona-user="${u.id}">${d.personas.filter(p=>p.id!=='administrator').map(p=>`<option value="${p.id}" ${p.id===(d.assignments.find(a=>a.user_id===u.id)?.persona||'operator')?'selected':''}>${e(p.name)}</option>`).join('')}</select></label>`}</div>`).join('')+`<p class="muted mt-4">Create real accounts in User Management, then assign their work persona here. Personas do not create sample users.</p>`):''}${panel('Audit trail',d.audit.length?d.audit.slice(0,30).map(a=>`<div class="record-row"><b class="text-sm">${e(a.action)}</b><p class="muted">${e(a.username||a.user_id)} · ${e(new Date(a.created_at).toLocaleString())}</p></div>`).join(''):'<p class="empty-state">Configuration changes and executions will be recorded here.</p>')}`;root.querySelector('#refreshPersonas').onclick=()=>load().catch(err=>notify(err.message,'danger'));root.querySelectorAll('[data-persona-user]').forEach(s=>s.onchange=()=>mutate('/personas','POST',{userId:s.dataset.personaUser,persona:s.value}).catch(err=>notify(err.message,'danger')))})}});
})();


/* Feature: 01-agent-studio.js */
(() => {
 const {e,panel,btn,input,json,form,value,mutate,mount,agentTools,runForm}=Workspace;
 Aether.registerFeature({id:'agent-builder',label:'Natural Language Builder',icon:'sparkles',description:'Describe the job, reference integrated tools, and review an executable reasoning agent.',mount({root,notify}){
  let prompt='',caret=null,selected=new Set(),modelId='',draftId=null,initialized=false,busy=false,error='';
  function render(d){if(!initialized){selected=new Set(d.tools.filter(t=>t.enabled).slice(0,24).map(t=>t.id));modelId=d.models.find(m=>m.default)?.id||d.models.find(m=>m.endpoint&&m.credentialConfigured)?.id||'';initialized=true}const draft=d.agentDrafts.find(x=>x.id===draftId);root.innerHTML=`<div class="grid grid-cols-1 xl:grid-cols-3 gap-5"><div class="xl:col-span-2">${panel('Describe your agent',`<p class="muted mb-4">The model receives the names, descriptions and input schemas of the tools you select. It proposes instructions and tool bindings. Generation does not invoke tools.</p>${!d.persona.configure?'<p class="workspace-note">Your persona can view agents but cannot build them.</p>':''}<form id="nlAgentForm"><label for="nlAgentPrompt">What should this agent do?</label><textarea id="nlAgentPrompt" class="detail-input" rows="7" maxlength="6000" required ${busy?'disabled':''} placeholder="Investigate an incident using @your integrated tool. If the observed result meets my condition, use @your change tool, then verify the outcome.">${e(prompt)}</textarea><div class="form-row"><div><label for="nlAgentModel">Builder and execution model</label><select id="nlAgentModel" class="detail-input" ${busy?'disabled':''} required><option value="">Select a model connection</option>${d.models.map(m=>`<option value="${m.id}" ${m.id===modelId?'selected':''}>${e(m.name)}${m.endpoint&&m.credentialConfigured?'':' · configuration incomplete'}</option>`).join('')}</select></div><div class="pt-6"><button type="button" id="nlModelSetup" class="text-sm text-blue-700">Open Model Management →</button></div></div>${!d.models.length?'<p class="workspace-note">Connect a model and save its credential before generating an agent.</p>':''}<p class="error-message" id="nlAgentError" role="alert">${e(error)}</p>${btn(busy?'Generating reviewed plan…':'Generate agent plan',`type="submit" ${busy||!d.persona.configure||!selected.size||!modelId?'disabled':''}`)}</form>`) }${draft?`<div class="mt-5">${panel('Review the proposed agent',`<p class="muted mb-4">${draft.status==='saved'?'This draft has been saved to Agent Garden.':'Review instructions, required input and bound tools before saving. The saved agent will call only its bound integrations.'}</p>${draft.missingCapabilities.length?`<div class="workspace-note"><b>Missing capabilities</b>${draft.missingCapabilities.map(x=>`<p>${e(x)}</p>`).join('')}<p class="mt-2">Integrate the missing tools or refine your request and generate again.</p></div>`:''}${draft.warnings.length?`<div class="workspace-note">${draft.warnings.map(x=>`<p>${e(x)}</p>`).join('')}</div>`:''}<form id="nlReviewForm">${input('nlReviewName','Agent name','required maxlength="100" value="'+e(draft.spec.name)+'"')}${input('nlReviewDescription','Purpose','maxlength="1000" value="'+e(draft.spec.description)+'"')}<label for="nlReviewInstruction">Execution instructions</label><textarea id="nlReviewInstruction" class="detail-input" rows="7" maxlength="6000" required>${e(draft.spec.instruction)}</textarea><label for="nlReviewSchema">Required run input (JSON schema)</label><textarea id="nlReviewSchema" class="detail-input font-mono" rows="6" required>${e(JSON.stringify(draft.spec.inputSchema,null,2))}</textarea><h3 class="font-semibold mb-3">Bound tools</h3>${draft.selectedToolIds.map(id=>{const t=d.tools.find(t=>t.id===id);return `<label class="block mb-3"><input type="checkbox" data-draft-tool="${id}" ${draft.spec.toolIds.includes(id)?'checked':''}> ${e(t?.name||'Removed integration')} <span class="badge">${e(t?.method||'Unavailable')}</span> ${t?.requiresApproval?'<span class="badge">Approval required</span>':''}</label>`}).join('')}<p id="nlSaveError" class="error-message" role="alert"></p>${btn('Save to Agent Garden',`type="submit" ${draft.status!=='draft'||draft.missingCapabilities.length||!d.persona.configure?'disabled':''}`)}${btn('Open Agent Garden','type="button" id="nlOpenGarden"',true)}</form>`)}</div>`:''}</div><aside>${panel('Integrated tools',`<p class="muted mb-4">Select the capabilities the builder may use. Insert a tool name into your description to refer to it.</p>${d.tools.length?d.tools.map(t=>`<article class="record-row"><label class="flex items-start gap-2"><input type="checkbox" data-select-nl-tool="${t.id}" ${selected.has(t.id)?'checked':''} ${!t.enabled||busy?'disabled':''}><span><b>${e(t.name)}</b><p class="muted">${e(t.description)}</p></span></label><div class="mt-2">${btn('Insert @'+e(t.name),`type="button" data-insert-tool="${t.id}" ${busy?'disabled':''}`,true)}${btn('Input schema',`type="button" data-nl-schema="${t.id}"`,true)}</div>${t.requiresApproval?'<p class="muted">Invoking this tool requires administrator approval.</p>':''}</article>`).join(''):'<p class="muted">No integrated tools yet. Register actual capabilities in Tool Integrations first.</p>'}<button id="nlToolSetup" type="button" class="text-sm text-blue-700 mt-4">Open Tool Integrations →</button>`)}${d.agentDrafts.length?`<div class="mt-5">${panel('Your draft history',d.agentDrafts.slice(0,12).map(x=>`<button data-open-agent-draft="${x.id}" class="block w-full text-left record-row text-sm"><b>${e(x.spec.name)}</b><p class="muted">${e(x.status)} · ${e(new Date(x.updatedAt).toLocaleString())}</p></button>`).join(''))}</div>`:''}</aside></div>`;
   const promptInput=root.querySelector('#nlAgentPrompt');promptInput.oninput=ev=>{prompt=ev.target.value;caret={start:ev.target.selectionStart,end:ev.target.selectionEnd}};promptInput.onselect=ev=>{if(document.activeElement===ev.target)caret={start:ev.target.selectionStart,end:ev.target.selectionEnd}};root.querySelector('#nlAgentModel').onchange=ev=>{modelId=ev.target.value;render(d)};root.querySelector('#nlModelSetup').onclick=()=>Aether.navigate('model-management');root.querySelector('#nlToolSetup').onclick=()=>Aether.navigate('tools');root.querySelectorAll('[data-select-nl-tool]').forEach(box=>box.onchange=()=>{if(box.checked&&selected.size>=24){box.checked=false;notify('Select up to 24 tools.','warn');return}box.checked?selected.add(box.dataset.selectNlTool):selected.delete(box.dataset.selectNlTool);render(d)});root.querySelectorAll('[data-insert-tool]').forEach(b=>b.onclick=()=>{const t=d.tools.find(t=>t.id===b.dataset.insertTool);const text=root.querySelector('#nlAgentPrompt');const start=caret?.start??prompt.length,end=caret?.end??start;const token=(start>0&&!/\s/.test(prompt[start-1])?' ':'')+'@'+t.name+(end<prompt.length&&!/\s/.test(prompt[end])?' ':'');prompt=prompt.slice(0,start)+token+prompt.slice(end);text.value=prompt;caret={start:start+token.length,end:start+token.length};text.focus();text.setSelectionRange(caret.start,caret.end)});root.querySelectorAll('[data-nl-schema]').forEach(b=>b.onclick=()=>{const t=d.tools.find(t=>t.id===b.dataset.nlSchema);detail(t.name+' · Input schema',json(t.inputSchema))});root.querySelectorAll('[data-open-agent-draft]').forEach(b=>b.onclick=()=>{draftId=b.dataset.openAgentDraft;render(d)});
   root.querySelector('#nlAgentForm').onsubmit=async ev=>{ev.preventDefault();if(busy||!d.persona.configure)return;busy=true;error='';render(d);try{const result=await AppAuth.api('/api/workspace/agents/draft',{method:'POST',body:JSON.stringify({prompt,modelId,toolIds:[...selected]})});draftId=result.draft.id;await Workspace.load()}catch(err){error=err.message}busy=false;render(Workspace.get())};root.querySelector('#nlOpenGarden')?.addEventListener('click',()=>Aether.navigate('agents'));root.querySelector('#nlReviewForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const b=ev.target.querySelector('[type=submit]');b.disabled=true;try{const spec={...draft.spec,name:value('nlReviewName'),description:value('nlReviewDescription'),instruction:value('nlReviewInstruction'),inputSchema:JSON.parse(value('nlReviewSchema')),toolIds:Array.from(root.querySelectorAll('[data-draft-tool]:checked'),x=>x.dataset.draftTool)};await mutate('/agent-drafts/'+draft.id+'/save','POST',{spec});notify('Agent saved to Agent Garden.','success');Aether.navigate('agents')}catch(err){root.querySelector('#nlSaveError').textContent=err.message;b.disabled=false}})
  }mount(root,render)
 }});
 Aether.registerFeature({id:'orchestrator',label:'Agent Orchestrator',icon:'git-branch',description:'Compose saved agents into ordered runs with explicit input and output handoffs.',mount({root,notify}){
  function edit(flow){const d=Workspace.get();if(!d.agents.length){notify('Create an agent in Agent Garden first.');Aether.navigate('agents');return}let stages=structuredClone(flow?.stages||[{agentId:d.agents[0].id,inputFrom:'input',input:{}}]);form(flow?'Edit orchestration':'Create orchestration',`${input('orchestrationName','Orchestration name','required maxlength="100" value="'+e(flow?.name||'')+'"')}${input('orchestrationDescription','Goal','maxlength="1000" value="'+e(flow?.description||'')+'"')}<p class="muted mb-4">Agents execute one at a time. Pass the original run input, the previous agent’s output, or fixed JSON into each stage. The run stops on a failed stage.</p><div id="orchestrationStages"></div>${btn('Add agent stage','type="button" id="addOrchestrationStage"',true)}<label class="block mt-4"><input id="orchestrationEnabled" type="checkbox" ${flow?.enabled===false?'':'checked'}> Enabled</label>`,()=>{capture();return mutate('/orchestrations'+(flow?'/'+flow.id:''),flow?'PUT':'POST',{name:value('orchestrationName'),description:value('orchestrationDescription'),enabled:document.getElementById('orchestrationEnabled').checked,stages,...(flow?{revision:flow.revision}:{})})});
   function capture(){stages=stages.map((s,i)=>({agentId:value('orchestrationAgent'+i),inputFrom:value('orchestrationSource'+i),input:value('orchestrationSource'+i)==='fixed'?JSON.parse(value('orchestrationFixed'+i)):{}}))}
   function renderStages(){document.getElementById('orchestrationStages').innerHTML=stages.map((s,i)=>`<article class="record-row"><div class="flex justify-between items-center"><b>Stage ${i+1}</b>${btn('Remove',`type="button" data-remove-orchestration-stage="${i}" ${stages.length===1?'disabled':''}`,true)}</div><div class="form-row"><div><label for="orchestrationAgent${i}">Agent from the Garden</label><select id="orchestrationAgent${i}" class="detail-input">${d.agents.map(a=>`<option value="${a.id}" ${a.id===s.agentId?'selected':''}>${e(a.name)} · ${a.mode==='reasoning'?'Reasoning':'Tool workflow'}</option>`).join('')}</select></div><div><label for="orchestrationSource${i}">Stage input</label><select id="orchestrationSource${i}" class="detail-input">${[['input','Original run input'],['previous','Previous agent output'],['fixed','Fixed JSON']].map(([id,label])=>`<option value="${id}" ${id===s.inputFrom?'selected':''}>${label}</option>`).join('')}</select></div></div><div id="orchestrationFixedWrap${i}" ${s.inputFrom==='fixed'?'':'hidden'}><label for="orchestrationFixed${i}">Fixed input</label><textarea id="orchestrationFixed${i}" class="detail-input font-mono" rows="3">${e(JSON.stringify(s.input||{},null,2))}</textarea></div></article>`).join('');stages.forEach((_,i)=>document.getElementById('orchestrationSource'+i).onchange=ev=>document.getElementById('orchestrationFixedWrap'+i).hidden=ev.target.value!=='fixed');document.querySelectorAll('[data-remove-orchestration-stage]').forEach(b=>b.onclick=()=>{try{capture();stages.splice(Number(b.dataset.removeOrchestrationStage),1);renderStages()}catch{notify('Enter valid fixed JSON before changing stages.','warn')}})}
   document.getElementById('addOrchestrationStage').onclick=()=>{if(stages.length>=6){notify('An orchestration supports up to six agents.','warn');return}try{capture();stages.push({agentId:d.agents[0].id,inputFrom:'previous',input:{}});renderStages()}catch{notify('Enter valid fixed JSON before adding a stage.','warn')}};renderStages()
  }
  mount(root,d=>{root.innerHTML=`<div class="page-actions">${d.persona.configure?btn('Create orchestration','id="addOrchestration"'):''}${btn('Refresh','id="refreshOrchestrations"',true)}<span class="muted">${d.orchestrations.length} saved orchestrations</span></div>${panel('Agent orchestrations',d.orchestrations.length?d.orchestrations.map(f=>`<article class="record-row"><div class="flex flex-wrap justify-between gap-3"><div><h3 class="font-semibold">${e(f.name)}</h3><p class="muted">${e(f.description)}</p></div><div>${d.persona.execute?btn('Run orchestration',`data-run-orchestration="${f.id}" ${!f.enabled?'disabled':''}`):''}${d.persona.configure?btn('Edit',`data-edit-orchestration="${f.id}"`,true)+btn('Remove',`data-remove-orchestration="${f.id}"`,true):''}</div></div><div class="orchestration-path">${f.stages.map((s,i)=>{const a=d.agents.find(a=>a.id===s.agentId);return `<div class="orchestration-node"><span class="badge">${i+1}</span><b>${e(a?.name||'Agent unavailable')}</b><p class="muted">${s.inputFrom==='previous'?'Previous agent output':s.inputFrom==='fixed'?'Fixed input':'Original run input'}</p><p class="muted">${a?agentTools(a).map(id=>e(d.tools.find(t=>t.id===id)?.name||'Missing tool')).join(' · '):''}</p></div>${i<f.stages.length-1?'<span class="orchestration-arrow" aria-hidden="true">→</span>':''}`}).join('')}</div>${Workspace.badge(f.enabled?'Enabled':'Disabled')}</article>`).join(''):'<p class="empty-state">No orchestrations yet. Compose real agents from the Garden and define how they pass results to one another.</p>')}`;root.querySelector('#addOrchestration')?.addEventListener('click',()=>edit());root.querySelector('#refreshOrchestrations').onclick=()=>Workspace.load().catch(err=>notify(err.message,'danger'));root.querySelectorAll('[data-edit-orchestration]').forEach(b=>b.onclick=()=>edit(d.orchestrations.find(f=>f.id===b.dataset.editOrchestration)));root.querySelectorAll('[data-run-orchestration]').forEach(b=>b.onclick=()=>runForm(d.orchestrations.find(f=>f.id===b.dataset.runOrchestration),'orchestrations',d.persona));root.querySelectorAll('[data-remove-orchestration]').forEach(b=>b.onclick=()=>mutate('/orchestrations/'+b.dataset.removeOrchestration,'DELETE').catch(err=>notify(err.message,'danger')))
  })
 }});
})();


/* Feature: infrastructure.js */
Aether.registerFeature({id:'infrastructure',label:'Infrastructure Integrations',icon:'network',description:'Connect private infrastructure through your outbound gateway. Credentials stay in your network; requests are read-only.',mount({root,notify,escapeHtml:e}){
 const admin=window.AETHER_USER?.role==='admin';let data;
 const field=(id,label,extra='')=>`<label for="${id}" class="text-xs font-semibold">${label}</label><input id="${id}" class="detail-input" required ${extra}>`;
 const call=(path,method='POST',body={})=>AppAuth.api(path,{method,body:JSON.stringify(body)});
 async function load(){try{data=await AppAuth.api('/api/infrastructure');render()}catch(err){root.textContent=err.message}}
 function render(){
  const active=data.gateways.filter(g=>g.active);
  root.innerHTML=`<section class="bg-blue-50 border border-blue-200 rounded-xl p-5 mb-6"><h2 class="font-bold text-sm">Private network connection</h2><p class="text-xs mt-2">Run the gateway on a machine that can reach your infrastructure. It polls this platform over outbound HTTPS. No inbound network access is required. Product credentials are read from environment variables on that machine.</p><p class="text-xs mt-2">REST adapters: NetApp ONTAP, VMware vCenter, ServiceNow, Kubernetes and Dynatrace Classic. Other products require a configured REST path or a local adapter. Autonomous remediation is not enabled.</p><a class="text-blue-700 text-xs underline mt-2 inline-block" href="/gateway-setup" target="_blank">Gateway installation and adapter guide</a></section><div class="grid grid-cols-1 xl:grid-cols-3 gap-6"><section class="bg-white border rounded-xl p-5"><h2 class="font-bold text-sm mb-3">Network gateways</h2>${active.length?active.map(g=>`<div class="border-b py-3"><b class="text-xs">${e(g.name)}</b><p class="text-xs text-slate-500">${g.last_seen?'Last heartbeat: '+e(new Date(g.last_seen).toLocaleString()):'Awaiting first gateway heartbeat'}</p>${admin?`<button class="text-xs text-rose-700 mt-1" data-revoke="${g.id}">Revoke access</button>`:''}</div>`).join(''):'<p class="text-xs text-slate-500">No gateways registered.</p>'}${admin?'<button id="pairGateway" class="detail-button mt-4">Register gateway</button>':''}</section><section class="xl:col-span-2 bg-white border rounded-xl p-5"><div class="flex justify-between"><h2 class="font-bold text-sm">Infrastructure connections</h2>${admin?'<button id="addInfra" class="detail-button">Add connection</button>':''}</div><div class="mt-4">${data.connections.length?data.connections.map(c=>{
   const j=data.jobs.find(j=>j.connection_id===c.id),pending=j&&['queued','running'].includes(j.status)&&Date.now()-j.created_at<120000;
   return `<article class="border rounded-lg p-4 mb-3"><div class="flex justify-between"><b class="text-sm">${e(c.name)}</b><span class="text-xs ${c.status==='Connected'?'text-emerald-700':'text-slate-600'}">${pending?'Request '+e(j.status):j&&['queued','running','expired'].includes(j.status)?'Request timed out · gateway unavailable':e(c.status)}</span></div><p class="text-xs text-slate-500 mt-1">${e(data.products.find(p=>p.id===c.product)?.name)} · Profile ${e(c.credential_ref)}</p><p class="text-xs mt-2">${e(c.message||'No live request has completed.')}</p>${c.checked_at?`<p class="text-xs text-slate-500">Last checked: ${e(new Date(c.checked_at).toLocaleString())}</p>`:''}<div class="flex gap-3 mt-3">${admin?`<button data-action="test" data-id="${c.id}" class="text-xs text-blue-700" ${pending?'disabled':''}>Test connection</button><button data-action="inventory" data-id="${c.id}" class="text-xs text-blue-700" ${pending?'disabled':''}>Sync inventory</button>`:''}<button data-detail="${c.id}" class="text-xs text-blue-700">View inventory (${c.inventory.length})</button>${admin?`<button data-action="delete" data-id="${c.id}" class="text-xs text-rose-700">Remove</button>`:''}</div></article>`
  }).join(''):'<p class="text-xs text-slate-500">Add a product connection to discover real infrastructure. No sample inventory is displayed here.</p>'}</div></section></div><section class="bg-white border rounded-xl p-5 mt-6"><h2 class="font-bold text-sm mb-3">Product catalog</h2><div class="grid grid-cols-2 md:grid-cols-4 gap-3">${data.products.map(p=>`<div class="bg-slate-50 border rounded-lg p-3"><b class="text-xs">${e(p.name)}</b><p class="text-xs text-slate-500 mt-1">${e(p.adapter==='REST'?'Read-only REST adapter':'Configure REST / local adapter')}</p></div>`).join('')}</div></section>`;
  if(admin){root.querySelector('#pairGateway').onclick=()=>{detail('Register private network gateway',`<form id="gatewayForm">${field('gatewayName','Gateway name','maxlength="80" placeholder="e.g. Corporate IT gateway"')}<button class="detail-button">Create gateway credential</button><p id="gatewayError" role="alert"></p></form>`);document.getElementById('gatewayForm').onsubmit=async ev=>{ev.preventDefault();try{const g=await call('/api/infrastructure/gateways','POST',{name:document.getElementById('gatewayName').value});detail('Gateway credential · shown once',`<p>Copy this token into AETHER_GATEWAY_TOKEN on your gateway machine. Treat it as a password.</p><textarea class="detail-input" readonly aria-label="Gateway token">${e(g.token)}</textarea><p>Download the gateway package from the installation guide. This credential can only poll read-only requests and return results for its own connections.</p><a href="/gateway-setup" target="_blank" class="text-blue-700 underline">Open setup guide</a>`);await load()}catch(err){document.getElementById('gatewayError').textContent=err.message}}};
  root.querySelector('#addInfra').onclick=()=>{if(!active.length){notify('Register a gateway first.','info');return}detail('Add infrastructure connection',`<form id="infraForm">${field('infraName','Connection name','maxlength="80"')}<label for="infraProduct">Product</label><select id="infraProduct" class="detail-input">${data.products.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select><label for="infraGateway">Gateway</label><select id="infraGateway" class="detail-input">${active.map(g=>`<option value="${g.id}">${e(g.name)}</option>`).join('')}</select>${field('infraRef','Local configuration alias','pattern="[a-zA-Z0-9_-]{1,64}" placeholder="e.g. netapp_prod"')}<p class="text-xs">The alias must match a profile in the gateway configuration. Store endpoint URLs and credentials on the gateway machine.</p><p id="infraError" role="alert"></p><button class="detail-button mt-3">Save connection</button></form>`);document.getElementById('infraForm').onsubmit=async ev=>{ev.preventDefault();try{await call('/api/infrastructure/connections','POST',{name:document.getElementById('infraName').value,product:document.getElementById('infraProduct').value,gatewayId:document.getElementById('infraGateway').value,credentialRef:document.getElementById('infraRef').value});closeDetail();await load()}catch(err){document.getElementById('infraError').textContent=err.message}}};
  root.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await call('/api/infrastructure/connections/'+b.dataset.id+(b.dataset.action==='delete'?'':'/'+b.dataset.action),b.dataset.action==='delete'?'DELETE':'POST');await load()}catch(err){notify(err.message,'danger');b.disabled=false}});
  root.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{try{await call('/api/infrastructure/gateways/'+b.dataset.revoke,'DELETE');await load()}catch(err){notify(err.message,'danger')}});
  }
  root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const c=data.connections.find(c=>c.id===b.dataset.detail);detail('Live inventory · '+c.name,c.inventory.length?`<table class="w-full text-xs text-left"><thead><tr><th>Name</th><th>Type</th><th>Status</th></tr></thead><tbody>${c.inventory.map(r=>`<tr class="border-t"><td class="p-3">${e(r.name)}</td><td>${e(r.type)}</td><td>${e(r.status)}</td></tr>`).join('')}</tbody></table><p class="text-xs mt-3">Latest successful snapshot · up to 50 resources. Checked ${e(c.checked_at||'')}.</p>`:'<p>No resources have been synchronized. Run Sync inventory after the gateway is connected.</p>')});
 }
 load();setInterval(()=>{if(document.getElementById('view-infrastructure')&&!document.getElementById('view-infrastructure').classList.contains('hidden'))load()},7000);
}});


/* Feature: knowledge-workspace.js */
(() => {
 const {e,panel,btn,input,json,form,value,mutate,mount}=Workspace;
 Aether.registerFeature({id:'knowledge-fabric',label:'Knowledge Fabric',icon:'library',description:'Shared operational knowledge with source discovery and topic relationships.',mount({root,notify}){
  let query='';
  function edit(doc){form(doc?'Edit source':'Add knowledge source',`${input('kfTitle','Source title','required maxlength="160" value="'+e(doc?.title||'')+'"')}${input('kfTags','Topics (comma-separated)','maxlength="300" value="'+e(doc?.tags||'')+'" placeholder="database, recovery"')}<label for="kfContent">Content</label><textarea id="kfContent" class="detail-input" rows="10" required maxlength="50000">${e(doc?.content||'')}</textarea><label for="kfFile">Import text or Markdown (up to 50 KB)</label><input id="kfFile" type="file" accept=".txt,.md,text/plain,text/markdown" class="detail-input"><p class="muted">Saved sources are shared with authenticated workspace users.</p>`,()=>mutate('/documents'+(doc?'/'+doc.id:''),doc?'PUT':'POST',{title:value('kfTitle'),tags:value('kfTags'),content:value('kfContent'),...(doc?{revision:doc.revision}:{})}));document.getElementById('kfFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;if(f.size>50000){notify('Choose a file under 50 KB.','warn');return}document.getElementById('kfContent').value=await f.text();if(!value('kfTitle'))document.getElementById('kfTitle').value=f.name}}
  function render(d){const docs=d.documents.filter(x=>(x.title+' '+x.tags+' '+x.content).toLowerCase().includes(query.toLowerCase()));root.innerHTML=`<div class="page-actions">${d.persona.configure?btn('Add source','id="kfAdd"'):''}${btn('Refresh','id="kfRefresh"',true)}<span class="muted">${d.documents.length} shared sources</span></div><div class="grid grid-cols-1 xl:grid-cols-3 gap-5"><div class="xl:col-span-2">${panel('Knowledge sources',`<label for="kfSearch">Search your fabric</label><input id="kfSearch" class="detail-input" placeholder="Search titles, topics or content" value="${e(query)}">${docs.length?docs.map(x=>`<article class="record-row"><div class="flex flex-wrap justify-between gap-3"><button data-source="${x.id}" class="text-blue-700 font-semibold text-left">${e(x.title)}</button><div>${d.persona.configure?btn('Edit',`data-edit-source="${x.id}"`,true)+btn('Remove',`data-remove-source="${x.id}"`,true):''}</div></div><p class="muted">${e(x.tags||'Untagged')} · ${e(new Date(x.updatedAt).toLocaleString())}</p><p class="text-sm mt-2">${e(x.content.slice(0,220))}${x.content.length>220?'…':''}</p></article>`).join(''):'<p class="empty-state">No matching sources. Add real runbooks or service documentation to start your knowledge fabric.</p>'}`)}</div><div>${panel('Topic relationships',d.documents.length?d.documents.map(x=>{const tags=x.tags.toLowerCase().split(',').map(t=>t.trim()).filter(Boolean);const related=d.documents.filter(o=>o.id!==x.id&&o.tags.toLowerCase().split(',').some(t=>tags.includes(t.trim())));return `<div class="record-row"><b class="text-sm">${e(x.title)}</b><p class="muted mt-1">${related.length?related.map(o=>e(o.title)).join(' · '):'No shared topics yet'}</p></div>`}).join(''):'<p class="muted">Documents sharing a topic are connected here.</p>')}</div></div>`;root.querySelector('#kfAdd')?.addEventListener('click',()=>edit());root.querySelector('#kfRefresh').onclick=()=>Workspace.load().catch(err=>notify(err.message,'danger'));root.querySelector('#kfSearch').oninput=ev=>{query=ev.target.value;const pos=ev.target.selectionStart;render(d);const s=root.querySelector('#kfSearch');s.focus();s.setSelectionRange(pos,pos)};root.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const x=d.documents.find(x=>x.id===b.dataset.source);detail(x.title,`<p class="muted">${e(x.tags)}</p><div class="chat-content">${e(x.content)}</div>`)});root.querySelectorAll('[data-edit-source]').forEach(b=>b.onclick=()=>edit(d.documents.find(x=>x.id===b.dataset.editSource)));root.querySelectorAll('[data-remove-source]').forEach(b=>b.onclick=()=>mutate('/documents/'+b.dataset.removeSource,'DELETE').catch(err=>notify(err.message,'danger')))}
  mount(root,render)
 }});
 Aether.registerFeature({id:'model-management',label:'Model Management',icon:'boxes',description:'Configure real model connections for your conversation interface.',mount({root,notify}){
  function edit(m){form(m?'Edit model connection':'Connect a model',`${input('mmName','Profile name','required maxlength="100" value="'+e(m?.name||'')+'"')}${input('mmProvider','Provider name','required maxlength="100" value="'+e(m?.provider||'')+'"')}${input('mmModel','Exact model identifier','required maxlength="150" value="'+e(m?.model||'')+'"')}${input('mmEndpoint','Chat completions endpoint','type="url" value="'+e(m?.endpoint||'')+'" placeholder="https://provider-host/v1/chat/completions"')}<p class="form-help">OpenAI-compatible chat completions API. Enter your provider’s actual endpoint and model identifier.</p>${input('mmSecret','Credential reference','pattern="MODEL_[A-Z0-9_]+" value="'+e(m?.secretRef||'')+'" placeholder="MODEL_PROVIDER_KEY"')}<p class="form-help">Save the provider key in Credentials and use its MODEL_ reference here. Profiles never contain API keys.</p>${input('mmContext','Context window (tokens)','type="number" min="1" max="10000000" required value="'+e(m?.context||32000)+'"')}${input('mmPurpose','Use case','maxlength="300" value="'+e(m?.purpose||'')+'"')}<label class="block mb-4"><input id="mmDefault" type="checkbox" ${m?.default?'checked':''}> Default conversation model</label>`,()=>mutate('/models'+(m?'/'+m.id:''),m?'PUT':'POST',{name:value('mmName'),provider:value('mmProvider'),model:value('mmModel'),endpoint:value('mmEndpoint'),secretRef:value('mmSecret'),context:Number(value('mmContext')),purpose:value('mmPurpose'),default:document.getElementById('mmDefault').checked,...(m?{revision:m.revision}:{})}))}
  mount(root,d=>{const admin=d.persona.id==='administrator';root.innerHTML=`<div class="page-actions">${admin?btn('Connect model','id="mmAdd"'):''}${btn('Refresh','id="mmRefresh"',true)}</div>${panel('Model connections',d.models.length?d.models.map(m=>`<article class="record-row"><div class="flex flex-wrap justify-between gap-3"><div><h3 class="font-semibold">${e(m.name)}</h3><p class="muted">${e(m.provider)} · ${e(m.model)} · ${m.context.toLocaleString()} context tokens</p><p class="muted mt-2">${e(m.purpose)}</p><div class="mt-2">${m.default?'<span class="badge">Default</span>':''} <span class="badge">${m.endpoint&&m.credentialConfigured?'Configured':'Configuration incomplete'}</span></div></div><div>${admin?btn('Edit',`data-edit-model="${m.id}"`,true)+btn('Remove',`data-remove-model="${m.id}"`,true):''}</div></div></article>`).join(''):'<p class="empty-state">No model connections. Connect a provider to generate live AI responses; conversations can also retrieve knowledge without a model.</p>')}`;root.querySelector('#mmAdd')?.addEventListener('click',()=>edit());root.querySelector('#mmRefresh').onclick=()=>Workspace.load().catch(err=>notify(err.message,'danger'));root.querySelectorAll('[data-edit-model]').forEach(b=>b.onclick=()=>edit(d.models.find(m=>m.id===b.dataset.editModel)));root.querySelectorAll('[data-remove-model]').forEach(b=>b.onclick=()=>mutate('/models/'+b.dataset.removeModel,'DELETE').catch(err=>notify(err.message,'danger')))})
 }});
 Aether.registerFeature({id:'conversations',label:'Conversations',icon:'messages-square',description:'Use shared knowledge or a connected model. Conversations are private to your account.',mount({root,notify}){
  let active=null,fresh=false,busy=false,selectedModel=null,selectionChanged=false;
  function render(d){if(!fresh&&!active)active=d.threads[0]?.id||null;const t=d.threads.find(x=>x.id===active);const modelId=selectionChanged?selectedModel:(t?t.modelId:d.models.find(m=>m.default)?.id||'');root.innerHTML=`<div class="grid grid-cols-1 lg:grid-cols-4 gap-5"><aside>${panel('Conversation history',`${d.persona.execute?btn('New conversation','id="cvNew"'):''}<div class="mt-4">${d.threads.map(x=>`<button data-thread="${x.id}" class="block w-full text-left text-sm p-3 rounded-lg mb-2 ${active===x.id?'bg-blue-50 text-blue-700':'bg-slate-50'}" ${busy?'disabled':''}>${e(x.title)}</button>`).join('')||'<p class="muted mt-3">No conversations yet.</p>'}</div>`)}</aside><div class="lg:col-span-3">${panel(t?.title||'Start a conversation',`<div class="page-actions"><label for="cvModel">Response mode</label><select id="cvModel" class="detail-input" style="width:auto;margin:0;max-width:100%" ${busy?'disabled':''}><option value="">Knowledge retrieval</option>${d.models.map(m=>`<option value="${m.id}" ${m.id===modelId?'selected':''}>${e(m.name)}</option>`).join('')}</select>${t&&d.persona.execute?btn('Delete','id="cvDelete"',true):''}</div><p class="muted">Knowledge retrieval returns source excerpts. A connected model generates answers using retrieved context. This conversation does not execute tool calls.</p><div id="cvMessages" aria-live="polite" style="max-height:520px;overflow:auto">${t?.messages.length?t.messages.map(m=>`<article class="chat-message ${m.role==='user'?'user':''}"><p class="text-sm font-semibold mb-2">${m.role==='user'?'You':'AETHER assistant'}</p><div class="chat-content">${e(m.content)}</div>${m.role==='assistant'?`<p class="muted mt-2">${m.mode==='model'?'Model response':'Knowledge retrieval'}</p>`:''}${(m.sources||[]).map(s=>`<details class="chat-sources"><summary>${e(s.title)}</summary><div class="chat-content">${e(s.content)}</div></details>`).join('')}</article>`).join(''):'<p class="empty-state">Ask about a runbook, service or operational procedure. Your workspace knowledge provides the source context.</p>'}</div>${d.persona.execute?`<form id="cvForm"><label for="cvPrompt">Message</label><textarea id="cvPrompt" class="detail-input" rows="3" required maxlength="4000" ${busy?'disabled':''} placeholder="What is the recovery procedure for this service?"></textarea><p id="cvError" class="error-message" role="alert"></p>${btn(busy?'Getting response…':'Send message',`type="submit" ${busy?'disabled':''}`)}</form>`:'<p class="workspace-note mt-4">Your auditor persona has read-only access.</p>'}`)}</div></div>`;root.querySelector('#cvModel').value=modelId||'';root.querySelector('#cvModel').onchange=ev=>{selectedModel=ev.target.value;selectionChanged=true};root.querySelector('#cvNew')?.addEventListener('click',()=>{if(busy)return;active=null;fresh=true;selectionChanged=false;render(d)});root.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{active=b.dataset.thread;fresh=false;selectionChanged=false;render(d)});root.querySelector('#cvDelete')?.addEventListener('click',async()=>{if(busy)return;try{await mutate('/threads/'+active,'DELETE');active=null;fresh=true;render(Workspace.get())}catch(err){notify(err.message,'danger')}});root.querySelector('#cvForm')?.addEventListener('submit',async ev=>{ev.preventDefault();if(busy)return;const prompt=root.querySelector('#cvPrompt').value.trim(),modelId=root.querySelector('#cvModel').value;if(!prompt)return;busy=true;render(d);try{const r=await AppAuth.api('/api/workspace/chat',{method:'POST',body:JSON.stringify({threadId:active,modelId,prompt})});active=r.thread.id;fresh=false;selectionChanged=false;await Workspace.load();busy=false;render(Workspace.get());const messages=root.querySelector('#cvMessages');messages.scrollTop=messages.scrollHeight}catch(err){busy=false;render(Workspace.get());root.querySelector('#cvPrompt').value=prompt;root.querySelector('#cvError').textContent=err.message}})}
  mount(root,render)
 }});
})();


/* Feature: live-operations.js */
(() => {
 const e=value=>escapeHtml(value??'');
 const count=v=>v===null||v===undefined?'Not reported':Number(v).toLocaleString();
 const duration=v=>v===null||v===undefined?'Not measured':(v/1000).toFixed(2)+' s';
 const money=(amount,currency)=>currency+' '+Number(amount).toFixed(6);
 const date=v=>v?new Date(v).toLocaleString():'Never checked';
 const json=v=>`<pre class="text-xs bg-slate-50 rounded p-3 overflow-auto">${e(JSON.stringify(v,null,2))}</pre>`;
 const panel=(title,body)=>`<section class="bg-white border border-navy-100 rounded-xl shadow-card p-4"><h2 class="text-sm font-bold mb-3">${title}</h2>${body}</section>`;
 const metric=(label,value,description)=>`<div class="bg-white border border-navy-100 rounded-xl shadow-card p-4"><p class="text-xs text-slate-500">${label}</p><p class="text-2xl font-extrabold font-mono text-navy-950 mt-2">${e(value)}</p><p class="text-xs text-slate-500 mt-2">${e(description)}</p></div>`;
 async function inspect(id){
  try{const {run}=await AppAuth.api('/api/python-agents/runs/'+id);const all=await AppAuth.api('/api/telemetry');const m=all.runs.find(r=>r.id===id);
   detail('Actual execution · '+run.status,`<p class="text-xs">${e(run.id)} · Requested by ${e(run.requested_by)}</p><div class="detail-grid">${kv('Execution duration',duration(m?.duration_ms))}${kv('Duration source',m?.duration_ms===null||m?.duration_ms===undefined?'Not reported':m.duration_source==='external'?'External backend reported':'Gateway measured')}${kv('Input tokens',count(m?.input_tokens))}${kv('Output tokens',count(m?.output_tokens))}${kv('Agent-reported cost',m?.cost===null||m?.cost===undefined?'Not reported':money(m.cost,m.currency))}</div><p class="text-xs">Duration comes from the gateway or the external backend, as identified below. Gateway timing excludes queue delay. Token usage and cost are reported by your agent, not independently reconciled with provider billing.</p>${run.error?`<p class="text-xs text-rose-700 mt-3">${e(run.error)}</p>`:''}${m?.telemetry_error?`<p class="text-xs text-amber-800 mt-3">${e(m.telemetry_error)}</p>`:''}<h3>Execution timestamps</h3>${json({queuedAt:date(run.created_at),finishedAt:date(run.finished_at)})}<h3>Input</h3>${json(run.input)}<h3>Output</h3>${run.output===null?'<p>No result returned.</p>':json(run.output)}`);
  }catch(error){Aether.notify(error.message,'danger')}
 }
 function table(runs,tokens=false){return runs.length?`<div class="overflow-auto"><table class="w-full text-xs text-left"><thead><tr><th>Agent</th><th>Status</th>${tokens?'<th>Input / output tokens</th><th>Model</th><th>Reported cost</th>':'<th>Queued</th>'}<th>Execution time</th><th>Details</th></tr></thead><tbody>${runs.map(r=>`<tr class="border-t"><td class="p-3">${e(r.agent_name||r.agent_id)}</td><td>${e(r.status)}</td>${tokens?`<td>${e(count(r.input_tokens))} / ${e(count(r.output_tokens))}</td><td>${e(r.model||'Not reported')}</td><td>${r.cost===null?'Not reported':e(money(r.cost,r.currency))}</td>`:`<td>${e(date(r.created_at))}</td>`}<td>${e(duration(r.duration_ms))}</td><td><button class="text-blue-700" data-actual-run="${r.id}">Inspect execution</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="text-xs text-slate-500">No recorded agent executions yet. Onboard an agent and run it to populate this view.</p>'}
 for(const [id,label,icon] of [['observability','Usage & Observability','chart-no-axes-combined']]){
  Aether.registerFeature({id,label,icon,description:id==='dashboard'?'Actual recorded agent executions and infrastructure snapshots.':'Token usage, costs and execution duration from recorded agent runs.',mount({root}){
   const heading=root.previousElementSibling.querySelector('h1');heading.textContent=id==='dashboard'?'SRE Incident & Agent Command Center':'Tokenomics & LLM Observability';
   let data;
   async function load(){try{data=await AppAuth.api('/api/telemetry');render()}catch(error){root.innerHTML=panel('Data unavailable',`<p role="alert" class="text-xs text-rose-700">${e(error.message)}</p><button id="retryLiveData" class="detail-button mt-3">Retry</button>`);root.querySelector('#retryLiveData').onclick=load}}
   function render(){const s=data.summary,a=data.aggregate;
    const header=`<div class="flex flex-wrap justify-between items-center gap-3 text-xs text-slate-500 mb-4"><span>Source: recorded agent executions · ${e(data.scope)} · Updated ${e(date(data.generatedAt))}</span><button id="refreshLiveData" class="text-blue-700 font-semibold">Refresh</button></div>`;
    if(id==='dashboard'){
     const done=s.succeeded+s.failed+s.expired;
     root.innerHTML=header+`<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">${metric('Enabled Python agents',data.agents.enabled,data.agents.total+' registered')}${metric('Average execution duration',duration(a.averageDurationMs),a.durationCoverage+' runs with measured or reported duration')}${metric('Successful executions',s.succeeded,done?s.succeeded+' of '+done+' terminal runs':'No completed executions yet')}${metric('Reported LLM spend',data.costs.length===1?money(data.costs[0].amount,data.costs[0].currency):data.costs.length?data.costs.length+' currencies':'Not reported',data.costs.length?'Agent-reported costs · all recorded runs':'No agent-reported costs yet')}</div>` + `<section class="rounded-xl border border-navy-100 bg-white shadow-card overflow-hidden mb-6"><div class="p-3 bg-slate-50 border-b border-navy-100 flex items-center gap-2"><span class="w-3 h-3 rounded-full bg-rose-400"></span><span class="w-3 h-3 rounded-full bg-amber-400"></span><span class="w-3 h-3 rounded-full bg-emerald-400"></span><h2 class="text-xs font-mono font-bold text-navy-900 ml-2">Agent Execution Feed</h2></div><div class="bg-navy-950 p-4 font-mono text-xs text-emerald-300 space-y-2 overflow-auto">${data.runs.length?data.runs.slice(0,8).reverse().map(r=>`<div><button class="text-left hover:text-white" data-actual-run="${r.id}">[${e(date(r.created_at))}] ${e(r.agent_name||r.agent_id)} · ${e(r.status)} · ${e(duration(r.duration_ms))} ↗</button></div>`).join(''):'[Awaiting agent executions] No recorded runs yet.'}</div></section>` +panel('Recent agent executions',table(data.runs))+`<div class="grid grid-cols-1 xl:grid-cols-2 gap-6 mt-6">${panel('Private-network gateway heartbeats',data.gateways.length?data.gateways.map(g=>`<div class="border-b py-3 text-xs"><b>${e(g.name)}</b><p>${!g.active?'Access revoked':g.last_seen&&Date.now()-Date.parse(g.last_seen)<30000?'Recent heartbeat':'Awaiting heartbeat / stale heartbeat'}</p><p class="text-slate-500">Last seen: ${e(date(g.last_seen))}</p></div>`).join(''):'<p class="text-xs text-slate-500">No gateways registered.</p>')}${panel('Infrastructure snapshots',data.connections.length?data.connections.map(c=>`<div class="border-b py-3 text-xs"><b>${e(c.name)}</b><p>${e(c.status)} · ${c.inventoryCount} resources in latest successful snapshot</p><p class="text-slate-500">Last checked: ${e(date(c.checked_at))}</p></div>`).join(''):'<p class="text-xs text-slate-500">No infrastructure connections configured. Infrastructure health is not available yet.</p>')}</div><div class="flex gap-4 mt-5"><button id="openActualAgents" class="detail-button">Python agents</button><button id="openActualInfra" class="detail-button">Infrastructure integrations</button></div>`;
     root.querySelector('#openActualAgents').onclick=()=>Aether.navigate('python-agents');root.querySelector('#openActualInfra').onclick=()=>Aether.navigate('infrastructure');
    }else{
     root.innerHTML=header+`<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">${metric('Reported input tokens',count(a.inputTokens),a.inputCoverage+' runs with input usage')}${metric('Reported output tokens',count(a.outputTokens),a.outputCoverage+' runs with output usage')}${metric('Total tokens with complete usage',count(a.totalTokens),a.tokenCoverage+' of '+s.total+' runs report both counts')}${metric('Average execution duration',duration(a.averageDurationMs),a.durationCoverage+' runs with duration')}</div>`+panel('Agent-reported costs',data.costs.length?data.costs.map(c=>`<p class="text-sm mb-2"><b>${e(money(c.amount,c.currency))}</b> · ${c.runs} runs reporting cost</p>`).join(''):'<p class="text-xs text-slate-500">Not reported. Costs appear only when your agent returns an actual amount and currency. No pricing assumptions or estimates are applied.</p>')+`<p class="text-xs text-slate-500 my-4">Missing usage stays unknown. Totals include reported values only. Currencies are kept separate. These figures are agent-reported and are not provider billing reconciliation.</p>`+panel('Usage by reported provider / model',data.models.length?`<div class="overflow-auto"><table class="w-full text-xs text-left"><thead><tr><th>Provider</th><th>Model</th><th>Runs with usage</th><th>Input tokens</th><th>Output tokens</th></tr></thead><tbody>${data.models.map(m=>`<tr class="border-t"><td class="p-3">${e(m.provider||'Not reported')}</td><td>${e(m.model||'Not reported')}</td><td>${m.runs}</td><td>${e(count(m.inputTokens))}</td><td>${e(count(m.outputTokens))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="text-xs text-slate-500">No model usage reported yet.</p>')+`<div class="mt-6">${panel('Execution usage and results',table(data.runs,true))}</div><p class="text-xs mt-4">Return usage in the _aether_telemetry field described in the <a href="/python-agent-setup" class="text-blue-700 underline" target="_blank">Python onboarding guide</a>. Agents running through another UI do not appear until their backend or wrapper reports executions here.</p>`;
    }
    root.querySelector('#refreshLiveData').onclick=load;root.querySelectorAll('[data-actual-run]').forEach(b=>b.onclick=()=>inspect(b.dataset.actualRun));
   }
   load();setInterval(()=>{if(!document.getElementById('view-'+id)?.classList.contains('hidden'))load()},5000);
  }});
 }
})();


/* Feature: python-agents.js */
Aether.registerFeature({id:'python-agents',label:'Python Agents',icon:'bot',description:'Onboard your existing Python agents, run them through a private gateway and inspect their results.',mount({root,notify,escapeHtml:e}){
 const admin=window.AETHER_USER?.role==='admin';let data,gatewayData;
 const api=(path,method='POST',body={})=>AppAuth.api(path,{method,body:JSON.stringify(body)});
 const input=(id,label,attrs='')=>`<label for="${id}" class="text-xs font-semibold">${label}</label><input id="${id}" class="detail-input" required ${attrs}>`;
 const date=v=>new Date(v).toLocaleString();
 async function load(){try{[gatewayData,data]=await Promise.all([AppAuth.api('/api/infrastructure'),AppAuth.api('/api/python-agents')]);render()}catch(err){root.textContent=err.message}}
 function render(){
  root.innerHTML=`<section class="bg-blue-50 border border-blue-200 rounded-xl p-5 mb-6"><h2 class="text-sm font-bold">Bring your existing agents</h2><p class="text-xs mt-2">Keep Python code, virtual environments and credentials inside your network. Register a locally configured agent alias here. The gateway runs its approved command with JSON input and returns the JSON result.</p><a href="/python-agent-setup" target="_blank" class="text-xs text-blue-700 underline inline-block mt-3">Python agent onboarding guide and example files</a></section><section class="bg-white border rounded-xl p-5"><div class="flex justify-between items-center"><h2 class="text-sm font-bold">Registered Python agents</h2>${admin?'<button id="onboardPython" class="detail-button">Onboard Python agent</button>':''}</div><div class="mt-4">${data.agents.length?data.agents.map(a=>{const gw=gatewayData.gateways.find(g=>g.id===a.gateway_id);const running=data.runs.some(r=>r.agent_id===a.id&&['queued','running'].includes(r.status));return `<article class="border rounded-xl p-4 mb-3"><div class="flex justify-between"><h3 class="text-sm font-bold">${e(a.name)}</h3><span class="text-xs text-slate-500">${a.enabled?'Enabled':'Disabled'}</span></div><p class="text-xs mt-2">${e(a.description)}</p><p class="text-xs text-slate-500 mt-2">Gateway: ${e(gw?.name||'Unavailable')} · Alias: ${e(a.agent_ref)} · ${a.mode==='change'?'Changes allowed with per-run approval':'Observation mode'}</p><p class="text-xs mt-1">${gw?.active?(gw.last_seen?'Gateway last seen '+e(date(gw.last_seen)):'Waiting for gateway heartbeat'):'Gateway access revoked'}</p><div class="flex gap-3 mt-3">${admin?`<button class="text-xs text-blue-700" data-run-agent="${a.id}" ${!a.enabled||!gw?.active||running?'disabled':''}>${running?'Run pending':'Run agent'}</button><button class="text-xs text-slate-600" data-toggle-agent="${a.id}">${a.enabled?'Disable':'Enable'}</button>`:''}<button class="text-xs text-blue-700" data-agent-info="${a.id}">Details</button></div></article>`}).join(''):'<p class="text-xs text-slate-500">No Python agents onboarded. Add an existing script or callable using a local gateway alias.</p>'}</div></section><section class="bg-white border rounded-xl p-5 mt-6"><h2 class="text-sm font-bold mb-4">Run history</h2>${data.runs.length?`<div class="overflow-auto"><table class="w-full text-xs text-left"><thead><tr><th>Agent</th><th>Status</th><th>Requested by</th><th>Started</th><th>Result</th></tr></thead><tbody>${data.runs.map(r=>`<tr class="border-t"><td class="p-3">${e(data.agents.find(a=>a.id===r.agent_id)?.name||r.agent_id)}</td><td>${e(r.status)}</td><td>${e(r.requested_by)}</td><td>${e(date(r.created_at))}</td><td><button data-run-detail="${r.id}" class="text-blue-700">Inspect run</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="text-xs text-slate-500">Run an agent to see its status, input and returned output here.</p>'}</section>`;
  if(admin){
   root.querySelector('#onboardPython').onclick=()=>{const gateways=gatewayData.gateways.filter(g=>g.active);if(!gateways.length){notify('Register a private-network gateway in Infrastructure Integrations first.','info');Aether.navigate('infrastructure');return}detail('Onboard existing Python agent',`<form id="onboardPythonForm">${input('pythonName','Agent name','maxlength="80"')}<label for="pythonDescription">Description</label><textarea id="pythonDescription" class="detail-input" maxlength="1000"></textarea><label for="pythonGateway">Private-network gateway</label><select id="pythonGateway" class="detail-input">${gateways.map(g=>`<option value="${g.id}">${e(g.name)}</option>`).join('')}</select>${input('pythonAlias','Local agent alias','pattern="[a-zA-Z0-9_-]{1,64}" placeholder="my_python_agent"')}<label for="pythonMode">Execution mode</label><select id="pythonMode" class="detail-input"><option value="observe">Observation</option><option value="change">May change infrastructure · approval per run</option></select><p class="text-xs mt-2">The alias must match an agents entry in your gateway configuration. Registering does not upload or execute your code. Install dependencies and use the appropriate service-account permissions on the gateway.</p><p id="pythonFormError" role="alert"></p><button class="detail-button mt-3">Onboard agent</button></form>`);document.getElementById('onboardPythonForm').onsubmit=async ev=>{ev.preventDefault();const submit=ev.target.querySelector('button');submit.disabled=true;try{await api('/api/python-agents','POST',{name:document.getElementById('pythonName').value,description:document.getElementById('pythonDescription').value,gatewayId:document.getElementById('pythonGateway').value,agentRef:document.getElementById('pythonAlias').value,mode:document.getElementById('pythonMode').value});closeDetail();await load();notify('Python agent registered.','success')}catch(err){document.getElementById('pythonFormError').textContent=err.message;submit.disabled=false}}};
   root.querySelectorAll('[data-toggle-agent]').forEach(b=>b.onclick=async()=>{const a=data.agents.find(a=>a.id===b.dataset.toggleAgent);try{await api('/api/python-agents/'+a.id,'PATCH',{enabled:!a.enabled});await load()}catch(err){notify(err.message,'danger')}});
   root.querySelectorAll('[data-run-agent]').forEach(b=>b.onclick=()=>{const a=data.agents.find(a=>a.id===b.dataset.runAgent);detail('Run Python agent · '+a.name,`<form id="pythonRunForm"><label for="pythonRunInput">Input (JSON object)</label><textarea id="pythonRunInput" class="detail-input font-mono" rows="7" maxlength="16000" required>{"task":"inspect infrastructure"}</textarea><p class="text-xs">Inputs and returned results are stored in this workspace and visible to its users. Keep credentials in the gateway environment.</p>${a.mode==='change'?'<label class="block text-sm mt-3"><input id="pythonApprove" type="checkbox" required> I approve this agent run, including its potential infrastructure changes.</label>':''}<p id="pythonRunError" role="alert"></p><button class="detail-button mt-3">${a.mode==='change'?'Approve and run':'Run agent'}</button></form>`);document.getElementById('pythonRunForm').onsubmit=async ev=>{ev.preventDefault();const submit=ev.target.querySelector('button');submit.disabled=true;try{const value=JSON.parse(document.getElementById('pythonRunInput').value);const r=await api('/api/python-agents/'+a.id+'/run','POST',{input:value,approved:document.getElementById('pythonApprove')?.checked||false});closeDetail();await load();notify('Run queued for your gateway.','success');await inspectRun(r.id)}catch(err){document.getElementById('pythonRunError').textContent=err instanceof SyntaxError?'Enter valid JSON input.':err.message;submit.disabled=false}}});
  }
  root.querySelectorAll('[data-agent-info]').forEach(b=>b.onclick=()=>{const a=data.agents.find(a=>a.id===b.dataset.agentInfo);detail('Python agent · '+a.name,`<p>${e(a.description)}</p><pre class="text-xs bg-slate-50 p-3 rounded mt-3 overflow-auto">${e(JSON.stringify({agents:{[a.agent_ref]:{mode:a.mode,...(a.mode==='change'?{allowChanges:true}:{}),command:['/path/to/venv/bin/python','/path/to/agent_adapter.py']}}},null,2))}</pre><p class="text-xs mt-3">Merge this agents entry into your local gateway configuration. Your adapter reads a JSON object from stdin and writes one JSON value to stdout. Use the onboarding guide to wrap an existing Python function.</p><a href="/python-agent-setup" target="_blank" class="text-blue-700 underline">Open onboarding guide</a>`)});
  root.querySelectorAll('[data-run-detail]').forEach(b=>b.onclick=()=>inspectRun(b.dataset.runDetail));
 }
 async function inspectRun(id){try{const {run}=await AppAuth.api('/api/python-agents/runs/'+id);detail('Python run · '+run.status,`<p class="text-xs">Run ID: ${e(run.id)} · Requested by ${e(run.requested_by)}</p><p class="text-xs mt-2">${e(run.error||(['queued','running'].includes(run.status)?'Waiting for gateway completion. Use Refresh run to check for results.':'Completed.'))}</p><h3 class="font-bold text-sm mt-4">Input</h3><pre class="text-xs bg-slate-50 p-3 overflow-auto">${e(JSON.stringify(run.input,null,2))}</pre><h3 class="font-bold text-sm mt-4">Output</h3><pre class="text-xs bg-slate-50 p-3 overflow-auto">${e(run.output===null?'No output returned.':JSON.stringify(run.output,null,2))}</pre><button id="refreshPythonRun" class="detail-button mt-3">Refresh run</button>`);document.getElementById('refreshPythonRun').onclick=()=>inspectRun(id)}catch(err){notify(err.message,'danger')}}
 load();setInterval(()=>{if(document.getElementById('view-python-agents')&&!document.getElementById('view-python-agents').classList.contains('hidden'))load()},5000);
}});


/* Feature: user-management.js */
if (window.AETHER_USER?.role === 'admin') {
 Aether.registerFeature({
  id:'users',label:'User Management',icon:'users-round',description:'Create user accounts and manage workspace access.',
  mount({root,notify}){
   root.innerHTML=`<div class="grid grid-cols-1 xl:grid-cols-3 gap-6"><section class="bg-white border border-navy-100 rounded-xl p-5 shadow-card"><h2 class="text-sm font-bold mb-4">Add a new user</h2><form id="createUserForm"><label for="newUserId" class="text-xs font-semibold">User ID</label><input id="newUserId" class="detail-input" autocomplete="off" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}" minlength="3" maxlength="40" required placeholder="e.g. sre-team"><label for="newUserPassword" class="text-xs font-semibold">Password</label><input id="newUserPassword" class="detail-input" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><label for="newUserPasswordConfirm" class="text-xs font-semibold">Confirm password</label><input id="newUserPasswordConfirm" class="detail-input" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><p class="text-xs text-slate-500 mb-3">New users start as Operations Analysts. Assign a different persona in Personas & Access. User management is reserved for administrators.</p><p id="createUserError" role="alert" class="text-xs text-rose-700 mb-2"></p><button id="createUserSubmit" class="detail-button" type="submit">Create user</button></form></section><section class="xl:col-span-2 bg-white border border-navy-100 rounded-xl p-5 shadow-card"><div class="flex items-center justify-between mb-4"><h2 class="text-sm font-bold">Workspace users</h2><button id="refreshUsers" class="text-xs text-blue-600 font-semibold">Refresh</button></div><div id="usersList" class="overflow-x-auto"></div></section></div>`;
   async function renderUsers(){
    const host=document.getElementById('usersList');host.textContent='Loading users…';
    try{const {users}=await AppAuth.api('/api/users');host.innerHTML=`<table class="w-full text-xs text-left"><thead><tr class="bg-slate-50 text-slate-500"><th class="p-3">User ID</th><th class="p-3">Role</th><th class="p-3">Status</th><th class="p-3 text-right">Actions</th></tr></thead><tbody>${users.map(user=>`<tr class="border-t border-slate-100"><td class="p-3 font-semibold">${escapeHtml(user.username)}</td><td class="p-3">${escapeHtml(user.role)}</td><td class="p-3 ${user.active?'text-emerald-700':'text-slate-500'}">${user.active?'Active':'Disabled'}</td><td class="p-3 text-right">${user.role==='admin'?'<span class="text-slate-500">Administrator</span>':`<button data-reset-user="${user.id}" class="text-blue-600 font-semibold mr-3">Reset password</button><button data-toggle-user="${user.id}" class="text-slate-600 font-semibold">${user.active?'Disable':'Enable'}</button>`}</td></tr>`).join('')}</tbody></table>`;
     host.querySelectorAll('[data-toggle-user]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;const target=users.find(u=>u.id===btn.dataset.toggleUser);try{await AppAuth.api('/api/users/'+target.id,{method:'PATCH',body:JSON.stringify({active:!target.active})});await renderUsers();notify('User access updated.','success')}catch(e){notify(e.message,'danger');btn.disabled=false}});
     host.querySelectorAll('[data-reset-user]').forEach(btn=>btn.onclick=()=>{
      const target=users.find(u=>u.id===btn.dataset.resetUser);
      detail('Reset password · '+target.username,`<form id="resetUserForm"><label for="resetUserPassword">New password</label><input id="resetUserPassword" class="detail-input" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><label for="resetUserConfirm">Confirm password</label><input id="resetUserConfirm" class="detail-input" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><p id="resetUserError" role="alert" class="text-rose-700"></p><button class="detail-button" type="submit">Save new password</button></form>`);
      document.getElementById('resetUserForm').onsubmit=async event=>{event.preventDefault();const password=document.getElementById('resetUserPassword').value;const error=document.getElementById('resetUserError');if(password!==document.getElementById('resetUserConfirm').value){error.textContent='Passwords do not match.';return}const submit=event.target.querySelector('button');submit.disabled=true;try{await AppAuth.api('/api/users/'+target.id,{method:'PATCH',body:JSON.stringify({password})});closeDetail();notify('Password reset. The user can sign in with the new password.','success')}catch(e){error.textContent=e.message;submit.disabled=false}};
     });
    }catch(e){host.textContent=e.message}
   }
   document.getElementById('refreshUsers').onclick=renderUsers;
   document.getElementById('createUserForm').onsubmit=async event=>{
    event.preventDefault();const error=document.getElementById('createUserError');error.textContent='';const password=document.getElementById('newUserPassword').value;if(password!==document.getElementById('newUserPasswordConfirm').value){error.textContent='Passwords do not match.';return}
    const submit=document.getElementById('createUserSubmit');submit.disabled=true;
    try{await AppAuth.api('/api/users',{method:'POST',body:JSON.stringify({username:document.getElementById('newUserId').value,password})});event.target.reset();await renderUsers();await Workspace.load();notify('New user created.','success')}catch(e){error.textContent=e.message}finally{submit.disabled=false}
   };
   renderUsers();
  }
 });
}

